#include <bits/stdc++.h>
using namespace std;

const int INF = 10000000;

int main() {
    int n, m, a, b, ans1 = INF, ans2 = INF;
    cin >> n >> m >> a >> b;

    int row1 = (a - 1) / m + 1;
    int row2 = (b - 1) / m + 1;
    int col1 = (a - 1) % m + 1;
    int col2 = (b - 1) % m + 1;

    if (row1 == row2) {
        ans1 = 1;
    } else if (row2 - row1 == 1) {
        ans1 = 2;
        if (col1 == 1 && b == n)
            ans1 = 1;
        else if (col1 == 1 && col2 == m)
            ans1 = 1;
    } else {
        ans1 = 3;
        if (b == n || col2 == m)
            --ans1;
        if (col1 == 1)
            --ans1;
    }

    ans2 = 3;
    if (col1 - 1 == col2)
        --ans2;

    cout << min(ans1, ans2) << '\n';

    return 0;
}

